import React, { useCallback, useEffect, useRef } from 'react';
import { motion, useReducedMotion } from 'framer-motion';
import { DISABLE_HEAVY_ANIMATIONS } from '../config/featureFlags';

;

// Lightweight wrapper that enforces best-practice animation patterns:
// - prefers-reduced-motion respected
// - default transitions use transform/opacity only
// - optional will-change promotion on pointerenter (removed on transitionend)
export default function Animated({
  children,
  promoteOnHover = true,
  whileHover,
  initial = { opacity: 0, y: 20 },
  animate = { opacity: 1, y: 0 },
  transition = { duration: 0.45, ease: 'easeOut' },
  staggerChildren = 0.04,
  ...rest
}) {
  const prefersReduced = useReducedMotion();
  const ref = useRef(null);

  // Ensure transform/opacity only in default animate to avoid layout paints
  const safeInitial = prefersReduced ? { opacity: 1, y: 0 } : initial;
  const safeAnimate = prefersReduced ? { opacity: 1, y: 0 } : animate;
  const safeWhileHover = prefersReduced ? undefined : whileHover;

  const onPointerEnter = useCallback(() => {
    if (!promoteOnHover || !ref.current) return;
    if (DISABLE_HEAVY_ANIMATIONS) return;
    try {
      ref.current.style.willChange = 'transform, opacity';
    } catch {
      /* noop */
    }
  }, [promoteOnHover]);

  const onTransitionEnd = useCallback((ev) => {
    // remove will-change after transition finishes to avoid persistent rasterization
    if (!ref.current) return;
    try {
      ref.current.style.willChange = 'auto';
    } catch {
      /* noop */
    }
  }, []);

  useEffect(() => {
    const el = ref.current;
    if (!el || !promoteOnHover) return;
    el.addEventListener('transitionend', onTransitionEnd);
    return () => el.removeEventListener('transitionend', onTransitionEnd);
  }, [promoteOnHover, onTransitionEnd]);

  return (
    <motion.div
      ref={ref}
      initial={safeInitial}
      animate={safeAnimate}
      whileHover={safeWhileHover}
      transition={transition}
      style={{ transformPerspective: 1000 }}
      {...(staggerChildren ? { variants: { visible: { transition: { staggerChildren } } } } : {})}
      onPointerEnter={onPointerEnter}
      {...rest}
    >
      {children}
    </motion.div>
  );
}
